"""
reliability_cards — one table per dataset ("disagreement reliability card") from results/finite_rater/*.json (T9 machinery) and results/rater_item/*.json when present.
Columns: panel, domain, raters per item m, K, a used, A1x (raw a-rater histogram vs exact mode+mean comparator; > 0 ⇒ the shape beyond mode and mean hurts a new-rater forecast),
ρ_smooth = X/M with the smoothed comparator (T9 definition), dense-curve crossover (A1 sign change) where available, donor-replacement support (A2 changed fraction),
and the rater–item decomposition (ΔLL M1−M0 thresholds, ΔLL M2−M1 dispersion, X_obs vs X_sim) when present.
Writes reports/RELIABILITY_CARDS.md.  Usage: python reliability_cards.py
"""
import json, glob, os, numpy as np
HERE = os.path.dirname(os.path.abspath(__file__))
DOMAIN = {"summeval_coherence8": "NLP summarisation", "summeval_relevance8": "NLP summarisation", "popquorn_off8": "NLP offensiveness", "popquorn_pol5": "NLP politeness", "hs2_help5": "NLP helpfulness",
          "emobank_reader_v5": "NLP valence", "csc6": "NLP sarcasm", "scalabrino": "SE code readability", "bw": "SE code readability", "dorn_java": "SE code readability (Java)", "dorn_python": "SE code readability (Python)",
          "dorn_cuda": "SE code readability (CUDA)", "dorn_all": "SE code readability", "crupi_ca": "SE code summary — content adequacy", "crupi_conc": "SE code summary — conciseness", "crupi_flu": "SE code summary — fluency",
          "mlcq3": "SE code-smell severity", "roy_ca": "SE code summary (Roy 2021)", "roy_conc": "SE code summary (Roy 2021)", "roy_flu": "SE code summary (Roy 2021)", "jb_naming": "SE readability — naming (JetBrains)",
          "jb_logical_separation": "SE readability — logical separation", "jb_sufficient_info": "SE readability — sufficient info", "jb_style_guide": "SE readability — style guide",
          "dices": "NLP conversational safety", "dices_raw": "NLP conversational safety (all 123 raters)", "dices990": "NLP conversational safety", "chaosnli_mnli": "NLP NLI (nominal)", "chaosnli_snli": "NLP NLI (nominal)", "chaosnli_alphanli": "NLP αNLI (binary control)"}
def fmt(x, d=4): return "—" if x is None else f"{x:+.{d}f}"
rows = []
for f in sorted(glob.glob(f"{HERE}/results/finite_rater/*.json")):
    name = os.path.basename(f)[:-5]
    if name in ("summary", "moderator"): continue
    r = json.load(open(f)); panel = r["panel"]; loo = name.endswith("_loo")
    for row in r["rows"]:
        e = row["est"]; c = row["ci95"]
        rows.append(dict(panel=panel, domain=DOMAIN.get(panel, "?"), m=r["m"], K=r["K"], n=r["n_items"], a=row["a"], loo=loo, A1=e["A1"], A1_ci=c["A1"], A1x=e["A1x"], rho=e["rho"], X=e["X"], M=e["M"],
                         a2=row.get("A2", {}).get("changed_fraction"), a2_itt=row.get("A2", {}).get("itt")))
    if "delta_ref" in r: rows[-1]["delta_ref"] = r["delta_ref"]["est"]
ri = {os.path.basename(f)[:-5]: json.load(open(f)) for f in glob.glob(f"{HERE}/results/rater_item/*.json")}
# ---- card table at a = m − 1 (loo) or the largest a of the curve
by_panel = {}
for row in rows:
    key = row["panel"]
    if key not in by_panel or (row["loo"] and not by_panel[key]["loo"]) or (row["loo"] == by_panel[key]["loo"] and row["a"] > by_panel[key]["a"]): by_panel[key] = row
out = ["# Disagreement reliability cards (generated by reliability_cards.py)", "",
       "A1x > 0: the raw a-rater histogram predicts a new rater WORSE than the exact mode-and-mean comparator (shape beyond mode+mean is net noise at this a). ρ = X/M with the smoothed comparator (T9); support = fraction of items whose histogram the donor replacement could change.", "",
       "| panel | domain | items | raters/item | K | a | A1x | A1 [95 %] | ρ_smooth | support | ΔLL thresholds | ΔLL dispersion | X_obs / X_sim(M1) / X_sim(M2) |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for key in sorted(by_panel, key=lambda k: (DOMAIN.get(k, "?").startswith("NLP"), DOMAIN.get(k, "?"), k)):
    row = by_panel[key]; rr = ri.get(key)
    dll1 = fmt(rr.get("dLL_M1_M0"), 3) if rr else "—"; dll2 = fmt(rr.get("dLL_M2_M1", rr.get("dLL_M2_M0")), 3) if rr else "—"
    xs = (f"{fmt(rr['X_obs'],5)} / {fmt(rr['X_sim'].get('M1', {}).get('X_mean'),5)} / {fmt(rr['X_sim'].get('M2', {}).get('X_mean'),5)}") if rr else "—"
    out.append(f"| {key} | {row['domain']} | {row['n']} | {row['m']} | {row['K']} | {row['a']}{' (loo)' if row['loo'] else ''} | {fmt(row['A1x'])} | {fmt(row['A1'])} [{fmt(row['A1_ci'][0])}, {fmt(row['A1_ci'][1])}] | {row['rho']:.2f} | {('%.2f' % row['a2']) if row['a2'] is not None else '—'} | {dll1} | {dll2} | {xs} |")
# ---- dense curves
curves = {}
for row in rows:
    if not row["loo"]: curves.setdefault(row["panel"], []).append(row)
if curves:
    out += ["", "## Dense-panel curves: A1 (smoothed comparator) and ρ by number of ratings a", ""]
    for key, rs in curves.items():
        rs = sorted(rs, key=lambda r: r["a"]); cross = next((f"{rs[i]['a']}–{rs[i+1]['a']}" for i in range(len(rs) - 1) if rs[i]["A1"] > 0 >= rs[i+1]["A1"]), "none ≤ %d" % rs[-1]["a"])
        out.append(f"- **{key}** ({DOMAIN.get(key,'?')}): " + "; ".join(f"a={r['a']}: A1 {r['A1']:+.4f}, A1x {r['A1x']:+.4f}, ρ {r['rho']:.2f}" for r in rs) + f". A1 sign change: {cross}" + (f"; Δ_ref {rs[-1]['delta_ref']:+.4f}" if 'delta_ref' in rs[-1] else ""))
os.makedirs(f"{HERE}/reports", exist_ok=True); open(f"{HERE}/reports/RELIABILITY_CARDS.md", "w").write("\n".join(out) + "\n"); print("\n".join(out))
